"""Episode 2 shot list. Each shot starts at an exact phrase of the narration (its anchor)
and runs until the next shot's anchor, so the shots cover the script word for word.
I(...) = still image (animate with zoom/pan in the edit), V(...) = image-to-video clip.
ch = character keys (CHARS in build.py); lt = lighting key (LIGHT); loc = location reference to upload.
"""

def I(a, lt, ch, sc, cam, md, loc=None):
    return dict(a=a, k="I", lt=lt, ch=ch, sc=sc, cam=cam, md=md, loc=loc)

def V(a, lt, ch, sc, cam, md, mv, cm, loc=None):
    return dict(a=a, k="V", lt=lt, ch=ch, sc=sc, cam=cam, md=md, mv=mv, cm=cm, loc=loc)

